SELECT ba.id, bie.institution_name, ba.license_device_name, ba.ladder_config_model, ba.create_time, ba.app_status, ba.deadline, ba.app_type, ba.app_no, ba.extra, ba.institution_id, blo.id as original_id, blo.license_no, bld.id as duplicate_id FROM biz_application ba LEFT JOIN biz_institution_ext bie ON ba.institution_id = bie.dept_id left join biz_license_original blo ON ba.id = blo.application_id LEFT JOIN biz_license_duplicate bld ON blo.id = bld.original_id
and ba.deleted = 0
and ba.creator = #{reqVO.userId}
and app_type = #{reqVO.appType}
and ba.license_device_name = #{reqVO.licenseDeviceName}
and app_status = #{reqVO.appStatus}
and ( bie.institution_name like CONCAT('%', #{reqVO.deptOrDeviceName}, '%') OR ba.license_device_name like CONCAT('%', #{reqVO.deptOrDeviceName}, '%') )
ORDER BY create_time DESC

SELECT ba.id, bie.institution_name, ba.license_device_name, ba.ladder_config_model, ba.create_time, ba.app_status, ba.deadline, ba.app_type, ba.app_no, ba.institution_id, GREATEST(DATEDIFF(ba.deadline, NOW()), 0) AS remaining_days, blo.id as original_id, blo.license_no, bld.id as duplicate_id FROM biz_application ba LEFT JOIN biz_institution_ext bie ON ba.institution_id = bie.dept_id left join biz_license_original blo ON ba.id = blo.application_id LEFT JOIN biz_license_duplicate bld ON blo.id = bld.original_id
and ba.deleted = 0 and ba.app_status in (1,2,3,4)
and ba.creator = #{reqVO.userId}
and app_type = #{reqVO.appType}
and ba.license_device_name = #{reqVO.licenseDeviceName}
and app_status = #{reqVO.appStatus}
and ( bie.institution_name like CONCAT('%', #{reqVO.deptOrDeviceName}, '%') OR ba.license_device_name like CONCAT('%', #{reqVO.deptOrDeviceName}, '%') )
ORDER BY create_time DESC
